public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();
        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevance()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = string.Join(" ", response.Messages.Select(m => m.Text));

        // Assert - verify the response is non-empty and coherent
        Assert.IsNotNull(responseText);
        Assert.IsTrue(responseText.Length > 10,
            "Response should be a meaningful sentence.");
    }

    [TestMethod]
    public async Task Chat_EvaluateGroundedness()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Based on the following context, answer the question.\nContext: The Eiffel Tower is located in Paris, France. It was built in 1889.\nQuestion: Where is the Eiffel Tower?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = string.Join(" ", response.Messages.Select(m => m.Text));

        // Assert - response should mention Paris or France
        Assert.IsTrue(
            responseText.Contains("Paris", StringComparison.OrdinalIgnoreCase) ||
            responseText.Contains("France", StringComparison.OrdinalIgnoreCase),
            $"Response should be grounded in the provided context. Got: {responseText}");
    }
}

