 using Aspire.Hosting;
 using Aspire.Hosting.Testing;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.Extensions.DependencyInjection;
 using Microsoft.Extensions.Hosting;
 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace MyApp.Evaluation;

 [TestClass]
 public class EvaluationTests
 {
     private static DistributedApplication? _app;
     private static IChatClient? _chatClient;

     [ClassInitialize]
     public static async Task Setup(TestContext context)
     {
         var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
         _app = await builder.BuildAsync();
         await _app.StartAsync();

         var httpClient = _app.CreateHttpClient("chat");
         _chatClient = _app.Services.GetService<IChatClient>();
     }

     [ClassCleanup]
     public static async Task Cleanup()
     {
         if (_app is not null)
         {
             await _app.StopAsync();
             await _app.DisposeAsync();
         }
     }

     [TestMethod]
     public async Task Chat_ReturnsRelevantResponse()
     {
         Assert.IsNotNull(_chatClient, "Chat client was not resolved from the app host.");

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await _chatClient.GetResponseAsync(messages);

         Assert.IsNotNull(response);
         Assert.IsTrue(response.Messages.Count > 0);
     }

     [TestMethod]
     public async Task Chat_EvaluateRelevance()
     {
         Assert.IsNotNull(_chatClient, "Chat client was not resolved from the app host.");

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
         };

         var response = await _chatClient.GetResponseAsync(messages);
         var responseText = string.Join(" ", response.Messages.Select(m => m.Text));

         Assert.IsNotNull(responseText);
         Assert.IsTrue(responseText.Length > 10,
             "Response should be a meaningful sentence.");
     }

     [TestMethod]
     public async Task Chat_EvaluateGroundedness()
     {
         Assert.IsNotNull(_chatClient, "Chat client was not resolved from the app host.");

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User,
                 "Based on the following context, answer the question.\n" +
                 "Context: The Eiffel Tower is located in Paris, France. It was built in 1889.\n" +
                 "Question: Where is the Eiffel Tower?")
         };

         var response = await _chatClient.GetResponseAsync(messages);
         var responseText = string.Join(" ", response.Messages.Select(m => m.Text));

         Assert.IsTrue(
             responseText.Contains("Paris", StringComparison.OrdinalIgnoreCase) ||
             responseText.Contains("France", StringComparison.OrdinalIgnoreCase),
             $"Response should be grounded in the provided context. Got: {responseText}");
     }
 }

